/// <summary>
///
/// </summary>
public static void CreateOrUpdateParameter(Name _name, ClassName _className, MethodName _methodName, anytype _value)
{
    TFMPageConfigParms   configParm;
    ttsbegin;
    select firstonly forupdate configParm where configParm.Name == _name &&  configParm.ClassName == _className && configParm.MethodName == _methodName;

    configParm.MethodName	= _methodName;
    configParm.Value		= [_value];
    configParm.ClassName	= _className;
    configParm.Name			= _name;
    configParm.ValueString	= strFmt('%1', _value);
    configParm.write();
    ttscommit;
}

public static void updateDeltaOnConfig(Object _class, Name _name)
{
    DictMethod              dm;
    ClassName				className = classId2Name(classIdGet(_class));;
    SysDictClass			DC = new SysDictClass(classIdGet(_class));
    TFMPageConfigParms		configParm;
    SysDictType				sdt;
    anytype                 value;
    anytype                 convertedValue;
    Types					testType;
    Types                   baseType;

    while select configParm where configParm.Name == _name && configParm.ClassName == className
    {
        dm = new DictMethod(UtilElementType::ClassInstanceMethod, className2Id(className), configParm.MethodName);
        if (!dm)
        {
            continue;
        }
        sdt = new SysDictType(dm.returnId());
        testType = dm.returnType();
        if (sdt != null  && testType == TypeS::UserType)
        {
            testType = sdt.baseType();
        }
        value = conPeek(configParm.Value,1);
        if(typeOf(value) == testType || dm.returnTypeName() == 'boolean') // if the type is not the same we ignore the value.
        {
            if(dm.returnTypeName() == 'boolean')
            {
                value = (value == 1 || value == '1' || strLwr(value) == 'true') ? true : false;
            }
            DC.callObject(configParm.MethodName,_class, value);
        }
        else if(testType ==Types::Enum)
        {
            baseType = dm.returnType();
            if (baseType == Types::UserType && dm.returnTypeName())
            {
                baseType = new DictType(extendedTypeName2Id(dm.returnTypeName())).baseType();
            }
            convertedValue = TFMDocCustomFunctionFlow::ConvertToType(value, baseType,baseType != Types::Enum ? extendedTypeId2name(dm.returnId()) : dm.returnTypeName());
            DC.callObject(configParm.MethodName,_class,convertedValue);
        }
    }
}

public static anytype getValue(Name _name, ClassName _className, MethodName _methodName, anytype _defaultValue = null)
{
    TFMPageConfigParms		configParm;

    select firstonly configParm where configParm.Name == _name && configParm.ClassName == _className && configParm.MethodName == _methodName;

    if (configParm.RecId)
    {
        return conPeek(configParm.Value,1);
    }

    return _defaultValue;
}

public static boolean exist(Name _name, ClassName _className, MethodName _methodName)
{
    TFMPageConfigParms		configParm;

    select firstonly RecId from configParm where configParm.Name == _name && configParm.ClassName == _className && configParm.MethodName == _methodName;

    return configParm.RecId != 0;

}

/// <summary>
/// Constructs the method name that will be used for the control and for the method name when saved in the database.
/// </summary>
/// <param name = "elementPath"></param>
/// <param name = "attributeName"></param>
/// <returns></returns>
public static str ConstructMethodNameForPageConfigParam(str elementPath, str attributeName )
{
    return elementPath + '_' + attributeName;
}
